import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { Refresh } from '@mui/icons-material';

const Gallery = () => {
  const [galleryData, setGalleryData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwCsCCWEYQlkzPTlrcoXOib7znjmSgkEk9C3EOPwSoJAwqehXiq1aGYWggy2qX1_jc8/exec';

  const fetchGalleryData = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Fetching gallery data...');
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const result = await response.json();
      console.log('API Response:', result);
      
      if (result.success && result.data) {
        const transformedData = result.data.map((item, index) => ({
          imageNo: item.imageNo ?? index + 1,
          fileName: item.fileName || `Image ${item.imageNo ?? index + 1}`,
          imageUrl: convertToDirectUrl(item.imageUrl)
        }));
        
        console.log('Transformed data:', transformedData);
        setGalleryData(transformedData);
        
        const initialLoadingStates = {};
        transformedData.forEach((item, index) => {
          initialLoadingStates[index] = true;
        });
        setImageLoadingStates(initialLoadingStates);
      } else {
        throw new Error(result.error || 'No data received from server');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError(`Error loading gallery: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Convert any Google Drive URL to direct download URL
  const convertToDirectUrl = (url) => {
    if (!url) return '';
    
    let fileId = '';
    
    if (url.includes('/file/d/')) {
      fileId = url.split('/file/d/')[1]?.split('/')[0];
    } else if (url.includes('uc?id=')) {
      fileId = url.split('uc?id=')[1];
    } else if (url.includes('open?id=')) {
      fileId = url.split('open?id=')[1];
    }
    
    if (fileId) {
      return `https://drive.google.com/uc?id=${fileId}`;
    }
    
    return url;
  };

  // Get thumbnail URL
  const getThumbnailUrl = (url) => {
    const fileId = url.split('uc?id=')[1];
    if (fileId) {
      return `https://drive.google.com/thumbnail?id=${fileId}&sz=w400`;
    }
    return url;
  };

  const handleImageLoad = (index) => {
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const handleImageError = (index, url) => {
    console.error(`Failed to load image ${index}:`, url);
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  // Determine columns based on screen size
  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  useEffect(() => {
    fetchGalleryData();
  }, []);

  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="200px"
        flexDirection="column"
        gap={2}
      >
        <CircularProgress />
        <Typography variant="body1">Loading photos...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 400 }}>
          {error}
        </Alert>
        <Button 
          variant="contained" 
          startIcon={<Refresh />}
          onClick={fetchGalleryData}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      
      
      {/* <Typography 
        variant="h6" 
        component="p" 
        align="center" 
        color="text.secondary"
        sx={{ mb: 3 }}
      >
        {galleryData.length} {galleryData.length === 1 ? 'photo' : 'photos'}
      </Typography> */}

      {galleryData.length === 0 ? (
        <Box textAlign="center" p={3}>
          <Typography variant="body1" color="text.secondary" gutterBottom>
            No photos found in the gallery.
          </Typography>
          <Button 
            variant="outlined" 
            startIcon={<Refresh />}
            onClick={fetchGalleryData}
            sx={{ mt: 2 }}
          >
            Refresh
          </Button>
        </Box>
      ) : (
        <Box
          sx={{
            columnCount: getColumns(),
            columnGap: 1,
            '& > *': {
              breakInside: 'avoid',
              marginBottom: 1,
              display: 'inline-block',
              width: '100%',
            }
          }}
        >
          {galleryData.map((item, idx) => {
            const thumbnailUrl = getThumbnailUrl(item.imageUrl);
            
            return (
              <Box
                key={idx}
                sx={{
                  borderRadius: 2,
                  overflow: 'hidden',
                  boxShadow: 1,
                  transition: 'all 0.3s ease',
                  backgroundColor: 'background.paper',
                  '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: 4,
                  },
                  position: 'relative',
                  display: 'inline-block',
                  width: '100%',
                }}
              >
                {/* Loader - Only show while image is loading */}
                {imageLoadingStates[idx] && (
                  <Box
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      backgroundColor: 'rgba(0,0,0,0.05)',
                      zIndex: 1,
                      minHeight: 200, // Only for loader, not the container
                    }}
                  >
                    <CircularProgress size={40} />
                  </Box>
                )}
                
                <Box
                  component="img"
                  src={thumbnailUrl}
                  alt={item.fileName}
                  loading="lazy"
                  sx={{
                    width: '100%',
                    height: 'auto',
                    display: 'block',
                    opacity: imageLoadingStates[idx] ? 0 : 1,
                    transition: 'opacity 0.3s ease',
                  }}
                  onLoad={() => handleImageLoad(idx)}
                  onError={() => handleImageError(idx, thumbnailUrl)}
                />
              </Box>
            );
          })}
        </Box>
      )}
    </Box>
  );
};

export default Gallery;
